submitOrder.function:
model.submitting = 0
// A card that could not be turned into a print PDF stops the order before FileMaker sees it.
if (model.pdfError && !model.submitError) model.submitError = String(model.pdfError)
if (model.submitError) return
// Keep the console readable: the base64 PDFs are long.
console.info('[Colliers order] Order confirmed: ' + (model.orderId || '(id from FileMaker)'), JSON.parse(JSON.stringify(model.orderPayload || {}, function (key, value) { return key === 'print_pdf_base64' && typeof value === 'string' ? '<base64 ' + value.length + ' chars>' : value })))
BF.namedAction('goConfirmed')
